import sys

PATH = 'generate_manuscript_nc.py'
src = open(PATH, encoding='utf-8').read().splitlines()

REPL = [
    (r"""p(f'We applied CKI to TCGA""",
     r"""p(f'We applied CKI to TCGA bulk RNA-seq across five cancer types (LUAD, LUSC, LIHC, KIRC, BRCA) [10,11], totalling {_tc["n_total"]:,} samples. At bulk resolution, averaging over tumor, stromal, and immune compartments, \u03c9 quantifies divergence between tissue states; we compare tumor\u2013tumor (TT), normal\u2013normal (NN), and tumor\u2013normal (TN) pairs within each cancer type (Fig. 4; Supplementary Fig. 4). A pan-cancer reversal emerged: NN pairs were more divergent than TT pairs in all five (mean NN/TT \u03c9: LUAD 2.46, KIRC 1.88, LUSC 1.71, BRCA 1.57, LIHC 1.10; cluster-bootstrap CI excluding 1 in four of five, LIHC excepted). Decomposition identified the mechanism: TT k_n exceeded NN k_n by 1.3\u20133.3-fold in every cancer type (95% CIs excluding 1 in all five) while TT k_f was equal to or higher\u2014the reversal reflects a more stable housekeeping baseline among adjacent non-tumor specimens, not smaller functional-gene divergence of tumor cells (Fig. 4a).')"""),
    (r"""p('To ask whether the ratio resolves""",
     r"""p('Stratifying LUAD tumors by driver mutation (61 EGFR-mutant, 120 KRAS-mutant, 311 wild-type) on per-tumor \u03c9 (Fig. 4b), KRAS-mutant tumors showed the highest tissue-level divergence (mean \u03c9 = 136.9 versus 115.4 wild-type and 122.2 EGFR-mutant; Kruskal-Wallis P = 7.8 \u00d7 10\u207b\u2077; Dunn\u2013Holm P \u2264 0.008 for both KRAS contrasts, P = 0.39 for EGFR\u2013wild-type; whole-tumor label-permutation confirmed; Section 3.13). The KRAS elevation was carried predominantly by a lower housekeeping baseline (~84% of the log-\u03c9 gap) with an accompanying functional component (KRAS versus EGFR under k_f alone, P = 0.015). Adjusting for ESTIMATE stromal/immune admixture left the KRAS\u2013wild-type difference significant (adjusted log-\u03c9 ratio 1.19, 95% CI [1.12, 1.26]) but abolished the apparent EGFR elevation (all adjusted P > 0.4); adjusting for smoking, alone or jointly with admixture, age, and sex, left the contrast essentially unchanged (\u0394\u03c9 +13.3, P = 1.4 \u00d7 10\u207b\u00b3). TP53 co-mutation and histological subtype were not adjusted for, so residual confounding remains; stratifications beyond LUAD are denominator-dominated vignettes (Supplementary Note 9).')"""),
    (r"""p('Four controls bound the interpretation""",
     r"""p('Four controls bound the interpretation (Supplementary Note 8). Composition adjustment left the pooled tumor-pair k_n coefficient essentially unchanged (\u22121.3% pooled, 95% CI \u22124.8% to +2.0%), and high-purity-half comparisons increased the TT k_n elevation in all five cancer types (e.g. LUAD 2.46 \u2192 2.86), so admixture can only weaken, not create, it. All TCGA statistics were recomputed under a linear probability mapping (the authoritative caliber), with key results preserved (LIHC effect size mapping-sensitive: 1.10 versus 1.31 softmax; Section 1.7). LUAD KRAS identity panels showed no MSigDB Hallmark enrichment [15] after correction (all q \u2265 0.24), composition-adjusted regressions retained the TT \u2265 NN k_f ordering in all five, and excluding the 32 cell-line-derived LIHC samples leaves the LIHC null unchanged (NN/TT 1.11, 95% CI [0.93, 1.30]). TCGA \u201cnormal\u201d samples are adjacent non-tumor, not healthy tissue, and per-tumor \u03c9 was not associated with overall survival (LIHC Cox HR per SD 1.07, 95% CI 0.88\u20131.31): we report all TCGA findings as tissue-level divergence at bulk resolution, pending single-cell or deconvolution-based validation.')"""),
    (r"""p(f'Of the {_h["n_pairs_total"]:,} Tabula Sapiens cell-type pairs""",
     r"""p(f'Of the {_h["n_pairs_total"]:,} Tabula Sapiens pairs, {DATA["cross_organ_n_total"]} are same-cell-type cross-organ comparisons, asking which cell types maintain identity regardless of residence and which are shaped by their organ (Fig. 5; Table 1; Supplementary Fig. 5). Among well-sampled types (n \u2265 5 pairs; upper block of Table 1), {t2[0][0]}s (mean \u03c9 = {t2[0][1]} \u00b1 {t2[0][2]}, n = {t2[0][3]}) and {t2[1][0]}s (mean \u03c9 = {t2[1][1]} \u00b1 {t2[1][2]}, n = {t2[1][3]}) were the most conserved, followed by {t2[2][0]}s and {t2_next[0]}s, with {mac[0]}s (n = {mac[3]}) intermediate; {last2[0][0]}s and {last2[1][0]}s were the most divergent, consistent with organ-specific endothelial programs [16], though both rest on n = 3 pairs\u2014sparsely sampled types (n = 1\u20133) carry no reliable signal.')"""),
    (r"""p(f'The cross-organ ranking showed little agreement""",
     r"""p(f'The cross-organ ranking agreed little with standard-metric rankings (Spearman r = {f'{min(DATA["cross_organ_spearman"].values()):.2f}'.replace('-', '\u2212')} to {f'{max(DATA["cross_organ_spearman"].values()):.2f}'.replace('-', '\u2212')}, n = {DATA["cross_organ_n_total"]} pairs; Supplementary Table 2), because CKI explicitly normalizes. A k_f-only control qualifies this (Supplementary Note 9): per-cell-type mean \u03c9 and mean k_f are only weakly concordant (r = 0.23, 95% CI [\u22120.08, 0.38], n = 17), the extremes reproduce but the middle does not. The ranking is thus a composite of functional divergence and baseline differences, and because the k_n anchor is not calibrated across cell types, cross-type gaps should be read descriptively (Discussion).')"""),
    (r"""p('We applied CKI to the Siletti""",
     r"""p('We applied CKI to the Siletti et al. human brain atlas [12] (~3.3 million nuclei, 108 regions), asking how much functional divergence separates the same cell type across regions, focusing on 888,263 non-neuronal nuclei in 10 major classes (neurons excluded: supercluster_term does not resolve neuronal subtypes). \u03c9 was computed for all same-cell-type cross-region pairs (31,764; Fig. 6; Supplementary Fig. 6; Supplementary Table 3); vascular cells and fibroblasts are heterogeneous superclusters, so their class-level \u03c9 values are supercluster averages.')"""),
    (r"""p('Class-mean \u03c9 spanned a regional gradient""",
     r"""p('Class-mean \u03c9 spanned a regional gradient from Bergmann glia and vascular cells (both 13.56) to astrocytes (82.75 \u00b1 44.98, n = 5,778 pairs)\u2014a full-data endpoint gradient of 6.10-fold. Because class-mean k_n is confounded by class size (below), this headline is an uncorrected upper bound: an equal-n downsample control attenuates it to 1.74 (95% CI [1.64, 1.84]) and a span-matched control (21 intra-cerebellar pairs) yields 3.68 (Supplementary Note 10); we co-report 6.10-fold (full-data) and 1.74-fold (size-balanced) throughout.')"""),
    (r"""p('To test whether this gradient exceeds chance""",
     r"""p('A cell-type-level block-shuffle null permuting library-to-region assignments (B = 1,000; Methods) tested whether the gradient exceeds chance: regional structure significantly raised mean \u03c9 for 4 of 10 classes (astrocytes at the permutation floor; OPCs, committed OPCs, fibroblasts P \u2264 0.030), 3 of 10 surviving Benjamini-Hochberg correction; a donor-stratified null leaves the same 3 of 10, and ependymal cells\u2014the one class moving against the conservative direction\u2014still do not survive (stratified q = 0.052). Microglia, oligodendrocytes, and Bergmann glia sit at or below the null expectation.')"""),
    (r"""p('Four analyses probe the robustness""",
     r"""p('Four analyses probe the gradient\u2019s robustness. First, restricting to same-donor region pairs preserved the extremes and a 4.50-fold gradient, so donor identity cannot explain it away (Supplementary Note 12). Second, the astrocyte-versus-Bergmann-glia contrast is predominantly a k_n effect (k_f differs 2.0-fold; mean k_n 3.2-fold): class-mean \u03c9 tracks k_n (Spearman \u03c1 = \u22120.73) but not k_f (\u03c1 = 0.09), and under a k_f-only ordering astrocytes rank third of ten\u2014the gradient chiefly reflects housekeeping stability across regions, not functional-gene divergence.')"""),
    (r"""p('Third, class-mean k_n correlates""",
     r"""p('Third, class-mean k_n correlates negatively with class size (Spearman \u03c1 = \u22120.648, P = 0.043), while class-mean \u03c9 is uncorrelated with all tested confounders (P \u2265 0.091; Supplementary Note 10). The equal-n residual is carried predominantly by the functional term (astrocyte/Bergmann-glia k_f ratio 2.09 equal-n, 2.03 full-data), whereas the k_n ratio reverses (equal-n 1.29, astrocyte higher; full-data 0.31)\u2014the full-data Bergmann-glia k_n elevation is largely a class-size artefact. Fourth, the gradient is robust to the group-size threshold in direction but not magnitude.')"""),
    (r"""p('The gradient aligns with known cell biology""",
     r"""p('The gradient aligns with known cell biology: vascular cells and fibroblasts are tissue-resident and locally replenished, consistent with low \u03c9 (though low class-level \u03c9 is not spatial uniformity [17,18]); microglia share core surveillance machinery [19]; astrocytes express region-specific ion channels, transporters, and secreted factors\u2014regional specialization compatible with, but not established by, the k_n-dominated ordering.')"""),
    (r"""p('The gradient suggests a residence/migration framework""",
     r"""p('The gradient suggests a residence/migration framework (recent migrants should show low inter-regional \u03c9; residents accumulate regional signatures), but the data provide no support: OPCs\u2014the most actively migrating non-neuronal population\u2014show the second-highest mean \u03c9 (40.62), and the screen shows no oligodendrocyte-lineage concentration (fold 0.77, P = 0.92); the framework remains hypothesis generation.')"""),
    (r"""p('Low CKI \u03c9 for a cell type""",
     r"""p('Low \u03c9 for a cell type across two regions indicates similarity beyond baseline expectation, with non-exclusive candidate mechanisms (developmental origin heterogeneity, colonization-route boundaries [20-22], postnatal migration [23,24]). The global verdict comes first: under a design-matched null that recomputes the full selection rule on every block-shuffle permutation, the expected number of Strong candidates is 148.3 across the 31,764-pair pool\u2014the 39 observed lie 3.8-fold below expectation (P(null count \u2265 39) = 1.0), and no candidate survives FDR correction (minimum q = 0.520). The catalogue is therefore a prioritized hypothesis list, not discoveries, and inherits the atlas\u2019s four-donor structure (Supplementary Note 11).')"""),
    (r"""p('The screen uses a multiplicative model""",
     r"""p('The screen uses a multiplicative model, expected_\u03c9 = \u03bc_ct \u00d7 \u03bc_pair / \u03bc_grand (Methods): a residual (observed/expected) well below 1 marks a cell type far less differentiated between two regions than expected from its own plasticity and the pair\u2019s divergence. Three tiers were defined: Strong (residual < 0.3, \u03c9 < 15, lowest \u03c9 in the pair), Moderate (residual < 0.5, \u03c9 < 25), Weak (residual < 0.75, \u03c9 < 35; Supplementary Fig. 8).')"""),
    (r"""p(f'Among {_br["total_pairs"]:,} comparisons""",
     r"""p(f'Criteria identified {_br["n_strong"]} ({_br["pct_strong"]:.2f}%) Strong, {_br["n_moderate"]:,} ({_br["pct_moderate"]:.2f}%) Moderate, and {_br["n_weak"]:,} ({_br["pct_weak"]:.2f}%) Weak candidates among {_br["total_pairs"]:,} comparisons (Supplementary Table 4). Under the block-shuffle null (B = 1,000; Supplementary Fig. 9), 31 Strong candidates showed raw P < 0.05 but none survived correction (minimum q = 0.520); the only sub-nominal stratified family is intra-cerebellar Bergmann-glia (m = 21; minimum q = 0.042). The microglial concentration (16 Strong) does not survive the design-matched null (fold 0.31, P = 0.990): we make no class-composition claim.')"""),
    (r"""p('A negative control confirms the null""",
     r"""p('A negative control confirms the null is calibrated by library-level, not regional, structure: libraries of every region were split into pseudo-regions and the identical test re-run on 127,756 pseudo-pairs (Supplementary Note 12; Supplementary Fig. 10)\u2014cross-region pseudo-pairs gave near-nominal tail rates, same-region halves a 37.6% lower-tail rate, confirming retained power.')"""),
    (r"""p('The catalogue converges on anatomically coherent themes""",
     r"""p('The catalogue converges on anatomically coherent themes. Microglial candidates (16 of 39) concentrate on visual-relay and orbitofrontal dissections (five pairs involve the lateral geniculate nucleus; Supplementary Note 11); mature-oligodendrocyte candidates (10, all raw P < 0.05) show a thalamo-temporal orientation crossing rather than following the dorsoventral origin boundary [25], their mechanistic basis unassigned (Supplementary Note 13). Astrocytes, fibroblasts, and ependymal cells contributed sparse candidates [26,27]; Bergmann glia, vascular cells, and choroid plexus none [26,28]. All are hypothesis-generating targets for spatial-transcriptomic and lineage follow-up [19].')"""),
    (r"""p('In summary, the block-shuffle re-analysis""",
     r"""p('In summary, the block-shuffle re-analysis substantially tempers the brain candidate catalogue: the class-level gradient is supported for 4 of 10 classes (3 of 10 after correction), no candidate survives FDR correction (minimum q = 0.520), and the Strong rule is anti-enriched relative to its null (148.3 expected versus 39 observed). An earlier per-pair label-shuffle implementation was anti-conservative (36.3% of P-values at the floor) by ignoring the 10x-library block structure; we position the entire candidate list as hypothesis-generating.')"""),
]

used = set()
for idx, (pre, new) in enumerate(REPL):
    hits = [i for i, l in enumerate(src) if l.strip().startswith(pre) and i not in used]
    if len(hits) != 1:
        print(f'FAIL[{idx}] matched {len(hits)}: {pre[:70]}')
        sys.exit(1)
    i = hits[0]
    used.add(i)
    ow = len(src[i].split()); nw = len(new.split())
    src[i] = new
    print(f'L{i+1}: {ow} -> {nw}')

open(PATH, 'w', encoding='utf-8').write('\n'.join(src) + '\n')
print('WROTE OK')
